@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;700&display=swap');

body {
  font-family: 'Roboto', sans-serif;
}

button:hover {
  background: #333;
  color: white;
}

input:focus {
  outline: 2px solid blue;
}

li:first-child {
  font-weight: bold;
}

li:last-child {
  color: gray;
}

li:nth-child(odd) {
  background: #f0f0f0;
}

button:active {
  transform: scale(0.95);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

input:enabled {
  border: 1px solid green;
}

.note::before {
  content: 'Note: ';
  font-weight: bold;
}

.card::after {
  content: '';
  display: block;
  height: 4px;
  background: goldenrod;
}

p::first-letter {
  font-size: 2em;
  font-weight: bold;
}

p::first-line {
  text-transform: uppercase;
}

input::placeholder {
  color: #999;
  font-style: italic;
}

textarea::placeholder {
  color: #aaa;
  font-size: 14px;
}

.button {
  background: blue;
  transition: background-color 0.3s;
}

.button:hover {
  background: darkblue;
}

.card {
  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
}

@keyframes fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

.banner {
  animation: fade 1s ease;
}

.box {
  animation: grow 1s ease forwards;
  animation-delay: 0.5s;
}

@keyframes grow {
  from { width: 0; }
  to { width: 100%; }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loader {
  width: 40px;
  height: 40px;
  border: 4px solid #ccc;
  border-top-color: #333;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

@media (max-width: 600px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

.card {
  width: 100%;
}

@media (min-width: 768px) {
  .card {
    width: 50%;
  }
}

@media (min-width: 1024px) {
  .card {
    width: 33%;
  }
}

.row {
  display: flex;
  flex-wrap: wrap;
}

.item {
  flex: 1 1 200px;
}

.hero {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

h1 {
  font-size: clamp(1.5rem, 4vw, 3rem);
}

p {
  font-size: clamp(1rem, 2vw, 1.25rem);
}

@media (max-width: 480px) {
  .menu { display: none; }
}

@media (min-width: 481px) and (max-width: 768px) {
  .menu { display: block; }
}

@media (min-width: 769px) {
  .menu { display: flex; }
}

:root {
  --main-color: #3498db;
  --space: 16px;
  --radius: 8px;
}

.button {
  background: var(--main-color);
  padding: var(--space);
  border-radius: var(--radius);
}

.card {
  --card-bg: #eee;
}

.card-title {
  background: var(--card-bg); /* works */
}

.main {
  color: var(--main-color); /* global */
}

.hero {
  background: var(--hero-color, #222);
}

.text {
  color: var(--text-color, black);
}

:root {
  --pad: 20px;
}

.container {
  padding: var(--pad);
}

@media (max-width: 600px) {
  :root {
    --pad: 10px;
  }
}

